style.css:
@-moz-document domain("google.com") {
/* Google background using Dropbox PNG */
body, html {
    background-image: url("https://dl.dropboxusercontent.com/s/oysy8k2tb9q1dwnkejxv5/image-2.png");
    background-size: cover;       /* fills the screen */
    background-repeat: no-repeat; /* no tiling */
    background-position: center;  /* centers the image */
}

/* Keep Google logo and search box above background */
#main, #hplogo, form[name="f"] {
    position: relative;
    z-index: 1;
}

/* Search box and buttons styling */
input, button {
    background-color: rgba(255, 255, 255, 0.8); /* semi-transparent white */
    color: #000;
    border-radius: 10px;
    border: 1px solid #FFB3CC; /* pink accent */
}

#gb, #hplogo {
    z-index: 2;
}
}
